// ═══════════════════════════════════════════════════
// SPLIT & NORMALIZE - PhantomBuster → items individuales
// ═══════════════════════════════════════════════════
const input = $input.all();
const results = [];

for (const item of input) {
  let raw = item.json;

  // PhantomBuster puede devolver output como string JSON o array directo
  if (raw.output && typeof raw.output === 'string') {
    try { raw = JSON.parse(raw.output); } catch(e) { raw = []; }
  } else if (raw.output && Array.isArray(raw.output)) {
    raw = raw.output;
  } else if (raw.resultObject && typeof raw.resultObject === 'string') {
    try { raw = JSON.parse(raw.resultObject); } catch(e) { raw = []; }
  } else if (Array.isArray(raw)) {
    // ya es array
  } else {
    raw = [raw];
  }

  if (!Array.isArray(raw)) raw = [raw];

  for (const lead of raw) {
    if (!lead || typeof lead !== 'object') continue;
    results.push({
      json: {
        fullName:          lead.fullName         || lead.name            || (lead.firstName + ' ' + lead.lastName).trim() || '',
        firstName:         lead.firstName        || '',
        lastName:          lead.lastName         || '',
        linkedinProfileUrl: lead.linkedinProfileUrl || lead.profileUrl || lead.url || '',
        profileUrl:        lead.profileUrl       || lead.linkedinProfileUrl || '',
        headline:          lead.headline         || lead.jobTitle        || lead.occupation || '',
        company:           lead.company          || lead.companyName     || lead.currentCompany || '',
        location:          lead.location         || lead.city            || '',
        connectionDegree:  lead.connectionDegree || '',
        email:             lead.email            || '',
        industry:          lead.industry         || '',
        _pbRaw:            JSON.stringify(lead)
      }
    });
  }
}

console.log(`[Normalize] Input items: ${input.length} → Output leads: ${results.length}`);
return results;

