// ═══════════════════════════════════════════════════
// SCORING MATRIX - Givra Tech
// Fuente de verdad: Sistema de Adquisición de Clientes
// ═══════════════════════════════════════════════════
const items = $input.all();
const results = [];

for (const item of items) {
  let enrichment = {};

  // 1. Parse OpenAI response
  try {
    const content =
      item.json?.choices?.[0]?.message?.content ||
      item.json?.message?.content ||
      item.json?.content ||
      '{}';
    const cleaned = content
      .replace(/```json\n?/gi, '')
      .replace(/```\n?/g, '')
      .trim();
    enrichment = JSON.parse(cleaned);
  } catch (e) {
    enrichment = {
      industry: 'other',
      estimated_employees: '10-50',
      pain_points: [],
      tech_signals: [],
      has_ads: false,
      has_reviews: false,
      has_ecommerce: false,
      notes: 'parse_error: ' + e.message
    };
  }

  // 2. Scoring matrix
  let score = 0;
  let productPrimary = 'AI Growth Audit';
  let productSecondary = 'LeadScoring Pro';

  const ind = (enrichment.industry || '').toLowerCase();
  const emp = enrichment.estimated_employees || '10-50';
  const tech = (enrichment.tech_signals || []).map(t => t.toLowerCase());
  const painCount = (enrichment.pain_points || []).length;

  // ── Industria fit (0-25 pts)
  if (ind === 'ecommerce' || ind === 'retail') {
    score += 25;
    productPrimary = enrichment.has_ads ? 'AdIntel' : 'StoreSpy';
    productSecondary = 'PricingOptimizer';
  } else if (ind === 'distribution') {
    score += 20;
    productPrimary = 'GeoGrowth';
    productSecondary = 'AI Growth Audit';
  } else if (ind === 'agency') {
    score += 15;
    productPrimary = 'LeadScoring Pro';
    productSecondary = 'Ghostwriter-Brand';
  } else if (ind === 'saas') {
    score += 12;
    productPrimary = 'LeadScoring Pro';
    productSecondary = 'ReviewMining';
  } else {
    score += 10;
  }

  // ── Tamaño empresa (0-20 pts)
  if (emp === '50-200' || emp === '200-500') score += 20;
  else if (emp === '10-50') score += 12;
  else if (emp === '500+') score += 8;
  else score += 5; // 1-10

  // ── Señales de dolor (0-30 pts)
  score += Math.min(painCount * 10, 30);

  // ── Señales de presupuesto (0-15 pts)
  if (enrichment.has_ads) { score += 10; }
  if (enrichment.has_ecommerce) { score += 5; }

  // ── Accesibilidad (0-10 pts)
  const hasEmail = !!(item.json._enrichPrompt && item.json.email);
  if (hasEmail) score += 5;
  score += 5; // LinkedIn activo (ya está en PhantomBuster)

  // ── Product override por tech stack
  if (tech.some(t => ['shopify','tiendanube','vtex','magento','woocommerce'].includes(t))) {
    productPrimary = 'StoreSpy';
    productSecondary = 'PricingOptimizer';
  }
  if (enrichment.has_reviews && ind !== 'ecommerce') {
    productPrimary = 'ReviewMining';
    productSecondary = 'GeoGrowth';
  }

  const tier = score >= 70 ? 'A' : score >= 50 ? 'B' : 'C';

  results.push({
    json: {
      ...item.json,
      // Scoring output (prefixed with _ to avoid Airtable column name conflict)
      _score:              score,
      _tier:               tier,
      _product_primary:    productPrimary,
      _product_secondary:  productSecondary,
      _industry:           enrichment.industry || '',
      _employees:          enrichment.estimated_employees || '',
      _pain_points:        JSON.stringify(enrichment.pain_points || []),
      _tech_signals:       JSON.stringify(enrichment.tech_signals || []),
      _has_ads:            enrichment.has_ads || false,
      _has_reviews:        enrichment.has_reviews || false,
      _has_ecommerce:      enrichment.has_ecommerce || false,
      _enrichment_notes:   enrichment.notes || ''
    }
  });

  console.log(`[Scoring] ${item.json.fullName || 'Unknown'} → Score: ${score} | Tier: ${tier} | Product: ${productPrimary}`);
}

return results;
